/* CONFIG - missed-call text-back with consent, dedupe and human escalation.
   PRODUCTION REQUIREMENTS (read docs/N8N-IMPLEMENTATION.md before going live):
   - US business texting over 10DLC REQUIRES A2P registration (brand + campaign)
     with your provider (e.g. Twilio) BEFORE any message can send.
   - Verify the webhook is really from your provider (signature header) in the
     verification step below. A secret URL alone is not sufficient.
   - This template ships in SAFE MODE: it prepares messages but DRY_RUN=true
     prevents sending until you flip it deliberately. */
const CONFIG = {
  DRY_RUN: true,                       // flip to false only after A2P approval + tests
  TENANTS: {                            // map your provider number -> business config
    "+12145550100": { tenant_id: "demo-hvac", business_name: "YOUR BUSINESS NAME",
      reply_template: "Hi, this is {business}. Sorry we missed your call. How can we help today?",
      quiet_hours: { start: 21, end: 7, tz_offset_hours: -5 },
      escalate_keywords: ["emergency","gas","fire","flood","injured","lawyer","refund"] }
  },
  SUPPRESSION_URL: $env.SUPPRESSION_URL || "YOUR_SUPPRESSION_STORE_URL",
  SUPPRESSION_KEY: $env.SUPPRESSION_KEY || "YOUR_SERVICE_KEY",
  PROVIDER_SIGNING_SECRET: $env.PROVIDER_SIGNING_SECRET || "YOUR_PROVIDER_SIGNING_SECRET"
};
const H = this.helpers;
const b = $input.first().json.body || {};
const hdr = $input.first().json.headers || {};

// 1. VERIFY PROVIDER SIGNATURE (Twilio: X-Twilio-Signature; see provider docs).
//    Template performs a presence check only; implement full HMAC validation for production.
if (!hdr["x-twilio-signature"] && !hdr["x-provider-signature"]) {
  return [{ json: { action: "reject", reason: "missing_signature" } }];
}

// 2. Identify tenant by the called number
const to = String(b.To || b.called || "").trim();
const from = String(b.From || b.caller || "").trim();
const callStatus = String(b.CallStatus || b.status || "").toLowerCase();
const eventId = String(b.CallSid || b.event_id || "").trim();
const tenant = CONFIG.TENANTS[to];
if (!tenant) return [{ json: { action: "ignore", reason: "unknown_tenant", to } }];
if (!eventId || !from) return [{ json: { action: "reject", reason: "malformed_event" } }];

// 3. Only respond to missed/unanswered outcomes
if (!["no-answer", "busy", "failed", "missed"].includes(callStatus)) {
  return [{ json: { action: "ignore", reason: "call_not_missed", callStatus } }];
}

// 4. Idempotency: providers retry webhooks. Use static data keyed by event id.
const store = $getWorkflowStaticData("global");
store.seen = store.seen || {};
const idem = eventId + ":missed_call_response";
if (store.seen[idem]) return [{ json: { action: "ignore", reason: "duplicate_event", eventId } }];
store.seen[idem] = Date.now();
// prune entries older than 48h
for (const k of Object.keys(store.seen)) if (Date.now() - store.seen[k] > 172800000) delete store.seen[k];

// 5. Suppression / consent check IMMEDIATELY BEFORE the send decision
let suppressed = false;
try {
  const q = await H.httpRequest({ url: CONFIG.SUPPRESSION_URL + "/rest/v1/suppressions?phone=eq." + encodeURIComponent(from) + "&select=id&limit=1",
    headers: { apikey: CONFIG.SUPPRESSION_KEY, Authorization: "Bearer " + CONFIG.SUPPRESSION_KEY }, json: true });
  suppressed = Array.isArray(q) && q.length > 0;
} catch (e) { /* if the suppression store is down, DO NOT send */ suppressed = true; }
if (suppressed) return [{ json: { action: "suppressed", tenant_id: tenant.tenant_id, eventId } }];

// 6. Quiet hours: do not text at 3am
const nowH = (new Date(Date.now() + tenant.quiet_hours.tz_offset_hours * 3600000)).getUTCHours();
const q = tenant.quiet_hours;
const inQuiet = q.start > q.end ? (nowH >= q.start || nowH < q.end) : (nowH >= q.start && nowH < q.end);
if (inQuiet) return [{ json: { action: "deferred_quiet_hours", tenant_id: tenant.tenant_id, eventId, from } }];

// 7. Approved template only - AI does not write this first message
const message = tenant.reply_template.replace("{business}", tenant.business_name)
  + " Reply STOP to opt out.";

return [{ json: {
  action: CONFIG.DRY_RUN ? "dry_run" : "send",
  tenant_id: tenant.tenant_id, eventId, to_number: from, from_number: to,
  message, escalate_keywords: tenant.escalate_keywords,
  note: CONFIG.DRY_RUN ? "SAFE MODE: no message sent. Flip CONFIG.DRY_RUN after A2P registration and tests." : ""
} }];

// Send branch - replace with your provider's node or HTTP call.
// Template logs instead of sending; wire your Twilio credential here for production.
const j = $input.first().json;
if (j.action !== "send") return [{ json: { ...j, sent: false } }];
/* PRODUCTION (example, Twilio node preferred over raw HTTP):
   POST https://api.twilio.com/2010-04-01/Accounts/{AccountSid}/Messages.json
   auth: Twilio credential; body: To=j.to_number, MessagingServiceSid=YOUR_MSG_SERVICE, Body=j.message */
return [{ json: { ...j, sent: false, note: "wire provider credential to enable sending" } }];
